export const KEYPAD_BY_CODE = new Map<number, KeyEntry>(KEYPAD.map((k): [number, KeyEntry] => [k.code, k]));

export function keyName(code: number): string {
  if (code === 0) return "";
  return KEYPAD_BY_CODE.get(code)?.name ?? `0x${code.toString(16).padStart(2, "0")}`;
}
